const when = input => { const date = new Date(input); return Number.isNaN(date.valueOf()) ? 'Unknown time' : date.toLocaleString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }); };
const viewNames = { agent: 'Agent', overview: 'Overview', prompts: 'Prompts', recording: 'Recording', sources: 'Sources', actions: 'Actions', project: 'Project' };
