  return `<section class="panel"><div class="panel-head"><h2>Question library</h2><span id="selection-count" class="pill">${state.checkedPrompts.size} selected · max 5 per measurement</span></div><div class="table-scroll"><table class="prompt-table"><thead><tr><th><input type="checkbox" data-check-visible aria-label="Select visible prompts" ${rows.length&&rows.every(q=>state.checkedPrompts.has(q.id))?'checked':''}></th><th>Prompt / topic</th>${shown('answers')?'<th>Answers</th>':''}${shown('visibility')?'<th>Visibility</th>':''}${shown('excluded')?'<th>Excluded</th>':''}${shown('intent')?'<th>Intent</th>':''}${shown('location')?'<th>Location</th>':''}${shown('status')?'<th>Status</th>':''}<th><span class="sr-only">Manage</span></th></tr></thead><tbody>${rows.map(query=>{const info=stats(samples.filter(s=>s.queryId===query.id)),topic=state.project.topics?.find(t=>t.id===query.topicId);return `<tr><td><input type="checkbox" data-select-prompt="${esc(query.id)}" aria-label="Select ${esc(query.text)}" ${state.checkedPrompts.has(query.id)?'checked':''}></td><td class="prompt-text"><button class="row-link" data-prompt="${esc(query.id)}">${esc(query.text)}</button><div class="row-meta">${esc(topic?.name||query.intent)} · ${query.branded?'Branded':'Unbranded'}<br><code>${esc(query.id)}</code>${query.previousVersionId?' · revised question':''}</div></td>${shown('answers')?`<td>${info.valid}</td>`:''}${shown('visibility')?`<td class="numeric">${rateLabel(info)}</td>`:''}${shown('excluded')?`<td>${info.failed}</td>`:''}${shown('intent')?`<td>${esc(query.intent)}</td>`:''}${shown('location')?`<td>${esc(query.country||state.project.country||'Unknown')}</td>`:''}${shown('status')?`<td>${tag(query.status||'active',query.status==='inactive'?'':'green')}</td>`:''}<td><button class="button small" data-edit-prompt="${esc(query.id)}">Edit</button></td></tr>`;}).join('')}</tbody></table></div>${rows.length?'':'<div class="empty">No prompts match this view. Add questions or change your filters.</div>'}<div class="panel-foot pagination"><span>${all.length} prompts · Page ${state.promptPage} of ${Math.max(1,Math.ceil(all.length/50))}</span><div><button class="button small" data-page="${state.promptPage-1}" ${state.promptPage<=1?'disabled':''}>Previous</button> <button class="button small" data-page="${state.promptPage+1}" ${state.promptPage*50>=all.length?'disabled':''}>Next</button></div></div></section>`;
