function projectPage() {
  const project = state.project, research = state.research?.result || state.research;
  return heading('Project', 'Keep your source material and review brand facts when needed. Fact review is not a prerequisite for collecting a diagnostic baseline.') + `<div class="stack">${brandSourceForm(project, true)}<section class="panel"><div class="panel-head"><h2>Brand profile</h2>${tag('Local workspace')}</div><div class="panel-body"><dl class="field-list"><dt>Brand</dt><dd>${esc(project.brand)}</dd><dt>Website</dt><dd><a href="${safeUrl(project.domain.includes('://') ? project.domain : `https://${project.domain}`)}" target="_blank" rel="noopener noreferrer">${esc(project.domain)}</a></dd><dt>Description</dt><dd>${esc(project.description || 'Not provided')}</dd><dt>Language</dt><dd>${esc(project.language || 'Not specified')}</dd><dt>Target market</dt><dd>${esc(project.country || 'Not specified')} · API region not verified</dd><dt>Research method</dt><dd>${esc(research?.methodology || 'See source provenance below')}</dd><dt>Question version</dt><dd>${project.queryVersion}</dd></dl></div></section><section class="panel"><div class="panel-head"><h2>Brand facts</h2><button class="button small" id="confirm-facts" ${running() ? 'disabled' : ''}>Confirm selected facts</button></div><div class="panel-foot">Review against the attached source before confirming. Unconfirmed site statements stay available for internal research.</div>${project.claims.map(claim => { const sourceIds = claim.status === 'conflict' ? claim.alternatives?.map(item => item.sourceId) || claim.sourceIds : claim.sourceIds; return `<div class="claim-item"><input type="checkbox" data-claim="${esc(claim.id)}" aria-label="Review ${esc(claim.label)}" ${claim.status === 'confirmed' ? 'checked disabled' : ''}><div><strong>${esc(claim.label)}</strong><p>${esc(claim.value)}</p><small>${claim.sourceIds.map(id => esc(project.sources.find(source => source.id === id)?.title || id)).join(' · ')}</small>${claim.status === 'confirmed' ? '' : `<select aria-label="Source for ${esc(claim.label)}" data-claim-source="${esc(claim.id)}">${[...new Set(sourceIds)].map(id => `<option value="${esc(id)}">${esc(project.sources.find(source => source.id === id)?.title || id)}</option>`).join('')}</select>`}</div>${tag(claim.status, claim.status === 'confirmed' ? 'green' : 'amber')}</div>`; }).join('') || '<div class="empty">No brand facts were extracted. Your question set can still be measured.</div>'}</section><section class="panel"><div class="panel-head"><h2>Website research sources</h2>${tag(`${project.sources.length} pages`)}</div>${project.sources.map(source => `<article class="source-document"><h3>${esc(source.title)}</h3>${source.url ? `<a href="${safeUrl(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.url)}</a>` : '<span class="form-note">User-provided source</span>'}<details><summary>Read collected text</summary><pre>${esc(source.text)}</pre></details></article>`).join('') || '<div class="empty">No collected website sources.</div>'}</section>${research?.warnings?.length ? `<div class="notice">${research.warnings.map(warning => `<p>${esc(warning)}</p>`).join('')}</div>` : ''}</div>`;
}
function nav(view, icon, child = false) { return `<button class="nav-button ${child ? 'nav-child' : ''}" data-view="${view}" ${state.view === view ? 'aria-current="page"' : ''}>${icon ? `<span class="nav-icon" aria-hidden="true">${icon}</span>` : ''}${viewNames[view]}</button>`; }
function render() {
  if (!state.project) return;
  const views = { agent, overview, prompts, recording, sources, actions, project: projectPage };
  document.title = `${viewNames[state.view]} · ${state.project.brand} · OpenGEO`;
  $('#workspace').innerHTML = `<div class="app-shell ${state.collapsed ? 'collapsed' : ''}"><aside class="rail"><a class="brand" href="/create-workspace"><span class="brand-symbol">O</span><div>OpenGEO<div class="brand-subtitle">AI VISIBILITY WORKSPACE</div></div></a><div class="project-identity"><span class="project-avatar">${esc(state.project.brand.slice(0,1))}</span><div><strong>${esc(state.project.brand)}</strong><small>${esc(state.project.domain)}</small></div></div><nav class="navigation" aria-label="Workspace navigation">${nav('agent','♧')}<div class="nav-section">Analysis</div>${nav('overview','▦')}<div class="nav-tracking"><span class="nav-icon" aria-hidden="true">⌁</span>Tracking</div>${nav('prompts','',true)}${nav('recording','',true)}${nav('sources','',true)}<div class="nav-section">Optimization</div>${nav('actions','↗')}<div class="nav-section">Management</div>${nav('project','⚑')}</nav><div class="rail-bottom"><a class="new-workspace" href="/create-workspace">＋ New workspace</a><div class="local-profile"><span class="live-dot"></span>Local workspace<br>English markets · Evidence first</div></div></aside><div class="workspace-area"><header class="topbar"><div class="breadcrumb"><button class="rail-toggle" data-toggle-rail aria-label="Toggle navigation">◫</button><span>${state.view === 'agent' ? 'Workspace' : ['overview','prompts','recording','sources'].includes(state.view) ? 'Analysis' : state.view === 'actions' ? 'Optimization' : 'Management'}</span><span aria-hidden="true">›</span><strong>${viewNames[state.view]}</strong></div><div class="top-actions">${state.run ? `<a class="button small" href="/api/runs/${esc(state.run.id)}/report${analysisQuery(state.analysisFilters)}">Export report ↗</a><a class="button small" href="/api/runs/${esc(state.run.id)}/report-html${analysisQuery(state.analysisFilters)}">HTML report</a>` : '<a class="button small" href="/?project=${esc(state.projectId)}&manage=1">Manage projects</a><a class="side-button" href="/create-workspace">New workspace</a>'}</div></header><main class="content" id="main">${state.error ? `<div class="notice error" role="alert">${esc(state.error)} <button class="button small" data-refresh>Retry</button></div>` : ''}${views[state.view]()}<footer class="footer-note"><span><span class="live-dot"></span>Local storage · No model calls on page load</span><span>First baseline · API and website evidence stay separate</span></footer></main></div></div>`;
}
async function refreshEvidence() { const [runs, evidence] = await Promise.all([api(`/api/runs?projectId=${encodeURIComponent(state.projectId)}`), api(`/api/projects/${encodeURIComponent(state.projectId)}/observations`)]); state.runs = runs; state.observations = evidence.observations || []; state.excluded = evidence.excluded || 0; await refreshAnalysis(); }
function schedulePoll() { clearTimeout(pollTimer); if (['queued','running'].includes(state.run?.status)) pollTimer = setTimeout(pollRun, 1500); }
async function pollRun() {
  const id = state.run?.id, selection = runSelection; if (!id) return;
  try { const run = await api(`/api/runs/${encodeURIComponent(id)}`); if (state.run?.id !== id || selection !== runSelection) return; state.run = run; state.error = ''; await refreshEvidence(); render(); schedulePoll(); }
  catch { state.error = 'The workflow connection was interrupted. Saved evidence is retained. Retry to reconnect.'; render(); }
}
async function openRun(id, view = 'agent') {
  const selection = ++runSelection; clearTimeout(pollTimer);
  let run;
  try { run = await api(`/api/runs/${encodeURIComponent(id)}`); }
  catch (error) { if (selection === runSelection) schedulePoll(); throw error; }
  if (selection !== runSelection) return;
  if (run.projectId !== state.projectId) throw new Error('This run belongs to another project.');
  state.run = run; state.view = view; await refreshAnalysis();
  if (selection !== runSelection) return;
  setLocation(); render(); schedulePoll();
}
function dialog(content) { const element = $('#evidence-dialog'); element.innerHTML = content; if (!element.open) element.showModal(); }
function openSample(id) {
  const sample = state.observations.find(item => item.id === id) || state.run?.samples.find(item => item.id === id);
  if (!sample) { toast('This answer is not available in the saved evidence.'); return; }
  const value = mentioned(sample);
  dialog(`<div class="dialog-head"><div><div class="eyebrow">Original answer</div><h2 id="evidence-title">${esc(sample.question)}</h2></div><button class="dialog-close" data-close-dialog aria-label="Close evidence">×</button></div><div class="dialog-body"><div class="button-row">${tag(sample.collectionStatus, sample.collectionStatus === 'failed' ? 'red' : '')}${tag(`Analysis: ${sample.analysisStatus}`)}${tag(value === null ? 'Mention: unknown' : value ? 'Brand mentioned' : 'Brand not mentioned', value ? 'green' : '')}</div><p class="dialog-meta section-gap">${esc(sample.model)} · ${when(sample.observedAt)}<br>Protocol: ${esc(sample.protocolId || 'Unknown')}<br>Observation ID: <code>${esc(sample.id)}</code>${sample.origin === 'browser' && sample.upstreamAttemptId ? `<br>Browser evidence bundle: <code>data/evidence/${esc(sample.upstreamAttemptId)}</code> (screenshot, DOM, answer)` : ''}</p>${sample.error ? `<div class="notice warning section-gap">${esc(sample.error)}</div>` : ''}<pre class="answer-text">${esc(sample.answer || 'No answer text was collected. This sample is excluded from mention-rate calculations.')}</pre><h3>Citations and links</h3>${sample.citations?.length ? sample.citations.map(citation => `<div class="citation">${tag(citation.kind.replaceAll('_',' '))}<br><a href="${safeUrl(citation.url)}" target="_blank" rel="noopener noreferrer">${esc(citation.url)}</a><p class="dialog-meta">Integrity: ${esc(citation.integrity || 'unverified')}${citation.integrity === 'mismatch' ? ' · Excluded from validated citations' : ''}</p></div>`).join('') : '<p class="dialog-meta section-gap">No citation evidence was returned for this answer.</p>'}</div>`);
}
function openPrompt(id) {
  const query = state.project.queries.find(item => item.id === id); if (!query) { toast('This question is not in the current library.'); return; }
  const samples = observations().filter(item => item.queryId === id);
  dialog(`<div class="dialog-head"><div><div class="eyebrow">Question history</div><h2 id="evidence-title">${esc(query.text)}</h2><p class="dialog-meta"><code>${esc(query.id)}</code></p></div><button class="dialog-close" data-close-dialog aria-label="Close evidence">×</button></div><div class="dialog-body">${samples.length ? cohortGroups(samples).map(group => `<section><h3>${esc(group[0].model)}</h3><p class="dialog-meta">${esc(group[0].protocolId || 'Unknown protocol')}</p>${group.map(sample => `<div class="dialog-observation"><p>${when(sample.observedAt)} · ${sample.collectionStatus === 'failed' ? 'Collection failed' : sample.analysisStatus !== 'completed' ? 'Analysis incomplete' : 'Answer saved'}</p><button class="button small" data-sample="${esc(sample.id)}">Read original answer</button></div>`).join('')}</section>`).join('') : '<p class="form-note">No observations for this question in the current scope. Select it to collect a first baseline.</p>'}</div>`);
}
document.addEventListener('keydown', () => document.body.classList.add('keyboard'));
document.addEventListener('pointerdown', () => document.body.classList.remove('keyboard'));
document.addEventListener('click', async event => {
  const button = event.target.closest('button'); if (!button) return;
  try {
    if (button.dataset.sourceLevel) { state.sourceLevel = button.dataset.sourceLevel; render(); return; }
    if (button.dataset.chart) { state.chartMetric = button.dataset.chart; render(); return; }
    if (button.dataset.view) { state.view = button.dataset.view; setLocation(); render(); }
    else if (button.hasAttribute('data-toggle-rail')) { state.collapsed = !state.collapsed; render(); }
    else if (button.hasAttribute('data-close-dialog')) $('#evidence-dialog').close();
    else if (button.dataset.sample) openSample(button.dataset.sample);
    else if (button.dataset.prompt) openPrompt(button.dataset.prompt);
    else if (button.dataset.run) await openRun(button.dataset.run);
    else if (button.hasAttribute('data-refresh')) { state.error = ''; await refreshEvidence(); if (state.run) state.run = await api(`/api/runs/${encodeURIComponent(state.run.id)}`); render(); schedulePoll(); }
    else if (button.dataset.action) { button.disabled = true; state.run = await api(`/api/runs/${encodeURIComponent(state.run.id)}/actions`, 'PATCH', { id: button.dataset.action, status: button.dataset.actionStatus }); render(); toast('Action status saved.'); }
    else if (button.id === 'confirm-facts') {
      const checked = [...document.querySelectorAll('[data-claim]:checked:not(:disabled)')];
      if (!checked.length) { toast('Select the facts you have checked against their sources.'); return; }
      button.disabled = true;
      for (const input of checked) { const source = [...document.querySelectorAll('[data-claim-source]')].find(item => item.dataset.claimSource === input.dataset.claim); if (!source?.value) throw new Error('A valid source is required for each fact.'); state.project = await api(`/api/projects/${encodeURIComponent(state.projectId)}/claims`, 'POST', { claimId: input.dataset.claim, sourceId: source.value }); }
      render(); toast('Selected facts confirmed with source references.');
    }
  } catch (error) { button.disabled = false; toast(error.message || 'The operation could not be completed.'); }
});
document.addEventListener('change', async event => {
  const input = event.target;
  if (input.matches('[data-analysis-run],[data-analysis-model],[data-analysis-channel],[data-analysis-days]')) { try { if (input.hasAttribute('data-analysis-run')) { await openRun(input.value, state.view); return; } else { const key = input.hasAttribute('data-analysis-model') ? 'model' : input.hasAttribute('data-analysis-channel') ? 'channel' : 'days'; state.analysisFilters[key] = input.value; } await refreshAnalysis(); render(); } catch (error) { toast(error.message); } return; }
  if (input.dataset.selectPrompt) { if(input.checked)state.checkedPrompts.add(input.dataset.selectPrompt);else state.checkedPrompts.delete(input.dataset.selectPrompt);setPromptChecks();$('#selection-count').textContent=`${state.checkedPrompts.size} selected · max 5 per measurement`; }
  else if (input.dataset.selectRecording) { const id = input.dataset.selectRecording; if (input.checked && state.recordingSelected.size >= 5) { input.checked = false; toast('Select up to five URLs.'); return; } input.checked ? state.recordingSelected.add(id) : state.recordingSelected.delete(id); render(); }
  else if (input.hasAttribute('data-check-visible')) { const rows=promptLibraryRows().slice((state.promptPage-1)*50,state.promptPage*50);for(const q of rows)input.checked?state.checkedPrompts.add(q.id):state.checkedPrompts.delete(q.id);setPromptChecks();render(); }
  else if (input.id === 'topic-filter') {state.topicFilter=input.value;state.promptPage=1;render();}
  else if (input.id === 'range-filter') { state.range = input.value; render(); }
  else if (input.id === 'model-filter') { state.model = input.value; render(); }
  else if (input.closest('#measurement-form')) { if (input.name === 'provider') state.provider = input.value; if (input.name === 'model') state.modelId = input.value; if (input.name === 'apiKey') state.apiKey = input.value; if (input.name === 'webSearch') state.webSearch = input.checked; if (input.name === 'channel') { state.channel = input.value; render(); } }
});
document.addEventListener('submit', async event => {
  if (event.target.id === 'recording-form') {
    event.preventDefault();
    const form = event.target, button = form.querySelector('button[type=submit]'), url = form.querySelector('input[name=url]').value, error = form.querySelector('.form-error');
    error.textContent = ''; button.disabled = true;
    try { await api(`/api/projects/${state.projectId}/recordings`, 'POST', { url }); form.reset(); await refreshRecordings(); render(); toast('URL added to the recording pool.'); }
    catch (failure) { error.textContent = failure.message; button.disabled = false; }
    return;
  }
  if (event.target.id !== 'measurement-form') return; event.preventDefault();
  if (running()) return;
  const data = new FormData(event.target), selected = state.project.queries.filter(query => state.selected.has(query.id));
  const browserChannel = state.channel !== 'api';
  const limit = browserChannel ? 3 : 5;
  if (!browserChannel) { state.provider = String(data.get('provider') || ''); state.modelId = String(data.get('model') || '').trim(); state.apiKey = String(data.get('apiKey') || ''); state.webSearch = data.get('webSearch') === 'on'; }
  if (!selected.length || selected.length > limit) { $('#measurement-error').textContent = `Select between one and ${limit} questions before starting.`; return; }
  if (!browserChannel && !state.modelId) { $('#measurement-error').textContent = 'Enter a model available to your provider account.'; return; }
  state.starting = true; render();
  try {
    const payload = browserChannel
      ? { projectId: state.projectId, mode: 'live', channel: 'browser', engine: state.channel, maxQuestions: selected.length, questions: selected.map(query => query.text), queryIds: selected.map(query => query.id) }
      : { projectId: state.projectId, mode: 'live', channel: 'api', provider: state.provider, model: state.modelId, apiKey: state.apiKey, maxQuestions: selected.length, questions: selected.map(query => query.text), queryIds: selected.map(query => query.id), webSearch: state.webSearch };
    const run = await api('/api/runs', 'POST', payload); state.run = await api(`/api/runs/${encodeURIComponent(run.id)}`); await refreshEvidence(); state.error = ''; setLocation(); }
  catch (error) { state.error = error.message || 'The measurement could not start. No result is assumed.'; }
  finally { state.starting = false; render(); schedulePoll(); }
});
async function initialize() {
  if (!state.projectId) { $('#workspace').innerHTML = '<main class="error-page"><h1>Choose a workspace</h1><p>Start with your website to create a brand profile and question set.</p><a class="button primary" href="/create-workspace">Create workspace</a></main>'; return; }
  try {
    [state.project, state.status] = await Promise.all([api(`/api/projects/${encodeURIComponent(state.projectId)}`), api('/api/status')]);
    state.provider = state.status.providers?.find(provider => provider.configured)?.id || state.status.providers?.[0]?.id || '';
    state.selected = new Set(state.project.queries.filter(query => !query.status || query.status === 'active').slice(0,5).map(query => query.id));
    state.checkedPrompts = new Set(state.selected);
    state.tableSettings = await api(`/api/projects/${encodeURIComponent(state.projectId)}/table-settings`);
    await refreshRecordings();
    await refreshEvidence();
    const requestedRun = params.get('run'), summary = state.runs.find(run => run.id === requestedRun) || state.runs.find(run => ['queued','running'].includes(run.status)) || state.runs[0];
    if (summary) { const run = await api(`/api/runs/${encodeURIComponent(summary.id)}?projectId=${encodeURIComponent(state.projectId)}`); if (run.projectId !== state.projectId) throw new Error('Run belongs to another project.'); state.run = run; } await refreshAnalysis();
    if (state.project.researchId) { try { state.research = await api(`/api/researches/${encodeURIComponent(state.project.researchId)}`); } catch { state.research = null; } }
    render(); schedulePoll();
  } catch (error) { $('#workspace').innerHTML = `<main class="error-page"><h1>Workspace unavailable</h1><p>${esc(error.message || 'The saved project could not be loaded.')}</p><button class="button primary" id="reload-workspace">Try again</button> <a class="button" href="/create-workspace">Create workspace</a></main>`; $('#reload-workspace').addEventListener('click', () => location.reload()); }
}
void initialize();

document.addEventListener('input',event=>{if(event.target.id==='prompt-search'){const pos=event.target.selectionStart;state.promptSearch=event.target.value;state.promptPage=1;render();$('#prompt-search').focus();$('#prompt-search').setSelectionRange(pos,pos);}});
document.addEventListener('click',async event=>{
 const button=event.target.closest('button');if(!button)return;
 try {
  if(button.dataset.collectRecording){button.disabled=true;const item=await api(`/api/projects/${state.projectId}/recordings/${encodeURIComponent(button.dataset.collectRecording)}/collect`,'POST',{});await refreshRecordings();render();toast(item?.status==='collected'?'Recording collected as a source.':(item?.error||'Collection failed; the URL stays in the pool.'));}
  else if(button.dataset.removeRecording){await api(`/api/projects/${state.projectId}/recordings/${encodeURIComponent(button.dataset.removeRecording)}`,'DELETE');await refreshRecordings();render();toast('Recording URL removed.');}
  else if(button.hasAttribute('data-generate-recording-prompts')){if(!state.recordingSelected.size)throw new Error('Select up to five collected URLs first.');const result=await api(`/api/projects/${state.projectId}/recordings/prompts`,'POST',{ids:[...state.recordingSelected]});state.project=await api(`/api/projects/${state.projectId}`);await refreshRecordings();state.view='prompts';state.promptStatus='suggested';setLocation();render();toast(`${result.added} suggested prompts added.`);}
  if(button.dataset.promptStatus){state.promptStatus=button.dataset.promptStatus;state.promptPage=1;state.checkedPrompts.clear();setPromptChecks();render();}
  else if(button.hasAttribute('data-add-prompts'))promptForm();
  else if(button.dataset.editPrompt)promptForm(state.project.queries.find(q=>q.id===button.dataset.editPrompt));
  else if(button.dataset.page){state.promptPage=Number(button.dataset.page);render();}
  else if(button.hasAttribute('data-export-prompts'))exportPrompts();
  else if(button.hasAttribute('data-measure-selected')){setPromptChecks();if(!state.selected.size)throw new Error('Select active prompts to measure.');state.view='agent';setLocation();render();}
  else if(button.dataset.promptBatch){if(!state.checkedPrompts.size)throw new Error('Select prompts first.');await promptMutation('prompts/batch','POST',{ids:[...state.checkedPrompts],operation:button.dataset.promptBatch,expectedVersion:state.project.queryVersion});state.checkedPrompts.clear();setPromptChecks();render();}
  else if(button.hasAttribute('data-add-topic')){dialog('<div class="dialog-head"><h2 id="evidence-title">New topic</h2><button class="dialog-close" data-close-dialog aria-label="Close evidence">×</button></div><form class="dialog-body form-grid" id="topic-form"><label>Topic name<input name="name" required maxlength="120"></label><p role="alert"></p><button class="button primary">Create topic</button></form>');$('#topic-form').onsubmit=async e=>{e.preventDefault();try{await promptMutation('topics','POST',{name:new FormData(e.target).get('name'),expectedVersion:state.project.queryVersion});$('#evidence-dialog').close();render();}catch(error){e.target.querySelector('[role=alert]').textContent=error.message;}};}
  else if(button.hasAttribute('data-assign-topic')){if(!state.checkedPrompts.size)throw new Error('Select prompts first.');dialog(`<div class="dialog-head"><h2 id="evidence-title">Assign topic</h2><button class="dialog-close" data-close-dialog aria-label="Close evidence">×</button></div><form class="dialog-body form-grid" id="assign-form"><label>Topic<select name="topicId">${topicOptions()}</select></label><p role="alert"></p><button class="button primary">Assign selected</button></form>`);$('#assign-form').onsubmit=async e=>{e.preventDefault();try{await promptMutation('prompts/batch','POST',{ids:[...state.checkedPrompts],operation:'assign-topic',topicId:new FormData(e.target).get('topicId'),expectedVersion:state.project.queryVersion});$('#evidence-dialog').close();render();}catch(error){e.target.querySelector('[role=alert]').textContent=error.message;}};}
  else if(button.hasAttribute('data-column-settings')){dialog(`<div class="dialog-head"><h2 id="evidence-title">Table columns</h2><button class="dialog-close" data-close-dialog aria-label="Close evidence">×</button></div><form class="dialog-body form-grid" id="columns-form">${['answers','visibility','excluded','intent','location','status'].map(c=>`<label class="check-label"><input type="checkbox" name="${c}" ${shown(c)?'checked':''}>${c}</label>`).join('')}<p role="alert"></p><button class="button primary">Save columns</button></form>`);$('#columns-form').onsubmit=async e=>{e.preventDefault();try{const data=new FormData(e.target);state.tableSettings=await api(`/api/projects/${state.projectId}/table-settings`,'PUT',{hiddenColumns:['answers','visibility','excluded','intent','location','status'].filter(c=>!data.has(c)),deltaDisplay:state.tableSettings.deltaDisplay,expectedVersion:state.tableSettings.version});$('#evidence-dialog').close();render();}catch(error){e.target.querySelector('[role=alert]').textContent=error.message;}};}
 } catch(error){toast(error.message);}
});

document.addEventListener('brand-sources-updated', event => { state.project = event.detail; render(); toast('Source saved. Review facts before publishing. Existing runs keep their snapshots.'); });
